  // The board is styled by the page's CSS and by CSS variables, none of which travel
  // with a serialised SVG, so copy the computed presentation values onto a clone.
  function exportBoard(scale, name) {
    var svg = document.getElementById('board');
    var clone = svg.cloneNode(true);
    var vb = (svg.getAttribute('viewBox') || '0 0 1000 500').split(/\s+/).map(Number);
    var props = ['fill', 'stroke', 'stroke-width', 'stroke-dasharray', 'stroke-dashoffset',
      'stroke-linecap', 'stroke-linejoin', 'font-size', 'font-family', 'font-weight',
      'font-style', 'text-anchor', 'dominant-baseline', 'opacity', 'fill-opacity', 'stroke-opacity'];
    var src = svg.querySelectorAll('*');
    var dst = clone.querySelectorAll('*');
    for (var i = 0; i < src.length; i++) {
      var cs = window.getComputedStyle(src[i]);
      for (var p = 0; p < props.length; p++) {
        var v = cs.getPropertyValue(props[p]);
        if (!v) continue;
        v = v.trim();
        if (v === 'auto' || v === 'normal' || v === 'initial') continue;
        if (v === 'none' && props[p] !== 'fill' && props[p] !== 'stroke') continue;
        dst[i].setAttribute(props[p], v);
      }
    }
    clone.removeAttribute('class');
    clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
    clone.setAttribute('width', vb[2]);
    clone.setAttribute('height', vb[3]);

    var xml = '<?xml version="1.0" encoding="UTF-8"?>' + new XMLSerializer().serializeToString(clone);
    var img = new Image();
    img.onload = function () {
      var canvas = document.createElement('canvas');
      canvas.width = Math.round(vb[2] * scale);
      canvas.height = Math.round(vb[3] * scale);
      var ctx = canvas.getContext('2d');
      ctx.fillStyle = window.getComputedStyle(document.querySelector('.stage')).backgroundColor || '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      canvas.toBlob(function (blob) {
        if (!blob) { toast('Could not render the board image'); return; }
        download(blob, name);
        toast('Board image saved');
      }, 'image/png');
    };
    img.onerror = function () { toast('Could not render the board image'); };
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(xml);
  }

  // One flat spec per case, so the same arithmetic serves the live setup and the presets.
  function liveSpec() {
    return {
      pivot: state.pivot,
      stickCG: state.stickCG,
      clampMass: state.clampMass,
      items: state.items.map(function (it) {
        return { role: it.role, x: it.x, mass: displayMass(it) };
      })
    };
  }

  function presetSpec(c) {
    var s = c.setup;
    return {
      pivot: typeof s.pivot === 'function' ? s.pivot(s) : s.pivot,
      stickCG: s.stickCG,
      clampMass: s.clampMass || 0,
      items: s.items.map(function (o) {
        return { role: o.role, x: o.x, mass: o.unknown ? null : o.mass };
      })
    };
  }

  function setupData(spec) {
    var clamp = spec.clampMass || 0;
    var rows = [], cw = 0, ccw = 0, hidden = false;
    for (var i = 0; i < spec.items.length; i++) {
      var it = spec.items[i];
      var r = Math.abs(round1(it.x - spec.pivot));
      var side = it.x < spec.pivot ? 'CCW' : (it.x > spec.pivot ? 'CW' : '—');
      if (it.mass == null) {
        hidden = true;
        rows.push({ el: it.role, m: '?', x: it.x, r: r, side: side, t: null });
        continue;
      }
      var m = it.mass + clamp;
      var t = m * (it.x - spec.pivot);
      if (t >= 0) cw += t; else ccw += -t;
      rows.push({ el: it.role, m: m, x: it.x, r: r, side: side, t: t });
    }
    var ts = state.stickMass * (spec.stickCG - spec.pivot);
    if (ts >= 0) cw += ts; else ccw += -ts;
    rows.push({
      el: 'meterstick at CG', m: state.stickMass, x: spec.stickCG,
      r: Math.abs(round1(spec.stickCG - spec.pivot)),
      side: Math.abs(spec.stickCG - spec.pivot) < 0.05 ? '—' : (spec.stickCG < spec.pivot ? 'CCW' : 'CW'),
      t: ts
    });
    return { rows: rows, cw: cw, ccw: ccw, hidden: hidden };
  }

  function csvCell(v) {
    var s = v == null ? '' : String(v);
    return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }

  function exportCasesCsv() {
    var toNm = function (gcm) { return gcm / 1000 * state.g / 100; };
    var head = ['case_id', 'case', 'element', 'mass_g', 'x_cm', 'lever_arm_cm', 'side',
      'torque_Nm', 'percent_difference'];
    var lines = [head.join(',')];

    for (var i = 0; i < CASES.length; i++) {
      var c = CASES[i];
      var d = setupData(c.id === state.caseId ? liveSpec() : presetSpec(c));
      for (var r = 0; r < d.rows.length; r++) {
        var row = d.rows[r];
        lines.push([
          c.id, c.chip, row.el,
          row.m === '?' ? '?' : num(row.m, row.m % 1 === 0 ? 0 : 1),
          num(row.x, 1), num(row.r, 1), row.side,
          row.t == null ? '' : toNm(row.t).toFixed(4), ''
        ].map(csvCell).join(','));
      }
      lines.push([c.id, c.chip, 'sum of counter-clockwise torques', '', '', '', '',
        d.hidden ? '?' : toNm(d.ccw).toFixed(4), ''].map(csvCell).join(','));
      lines.push([c.id, c.chip, 'sum of clockwise torques', '', '', '', '',
        d.hidden ? '?' : toNm(d.cw).toFixed(4), ''].map(csvCell).join(','));
      lines.push([c.id, c.chip, 'percent difference', '', '', '', '', '',
        (d.hidden || d.cw + d.ccw === 0) ? '' :
          (Math.abs(d.cw - d.ccw) / ((d.cw + d.ccw) / 2) * 100).toFixed(2)].map(csvCell).join(','));
    }

    var csv = '\ufeff' + lines.join('\r\n') + '\r\n';
    download(new Blob([csv], { type: 'text/csv;charset=utf-8' }), 'torque-balance-all-cases.csv');
    toast('Exported ' + CASES.length + ' cases to CSV');
  }

  /* ============================================================
     Storage & cases
     ============================================================ */","allowMultiple":false}]}}


