  function download(blob, name) {
    var a = document.createElement('a');
    var u = URL.createObjectURL(blob);
    a.href = u;
    a.download = name;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(u); a.remove(); }, 1000);
  }

  // The board is styled by the page's CSS and by CSS variables, none of which travel
  // with a serialised SVG, so copy the computed presentation values onto a clone.
  function exportBoard(scale, name) {
    var svg = document.getElementById('board');
    var clone = svg.cloneNode(true);
    var vb = (svg.getAttribute('viewBox') || '0 0 1000 500').split(/\s+/).map(Number);
    var props = ['fill', 'stroke', 'stroke-width', 'stroke-dasharray', 'stroke-dashoffset',
      'stroke-linecap', 'stroke-linejoin', 'font-size', 'font-family', 'font-weight',
      'font-style', 'text-anchor', 'dominant-baseline', 'opacity', 'fill-opacity', 'stroke-opacity'];
    var src = svg.querySelectorAll('*');
    var dst = clone.querySelectorAll('*');
    for (var i = 0; i < src.length; i++) {
      var cs = window.getComputedStyle(src[i]);
      for (var p = 0; p < props.length; p++) {
        var v = cs.getPropertyValue(props[p]);
        if (!v) continue;
        v = v.trim();
        if (v === 'auto' || v === 'normal' || v === 'initial') continue;
        if (v === 'none' && props[p] !== 'fill' && props[p] !== 'stroke') continue;
        dst[i].setAttribute(props[p], v);
      }
    }
    clone.removeAttribute('class');
